-- Retire l'équipement à fabriquer et les rangs, rend aux récompenses leurs chiffres d'origine et aux marchands
-- de Razor Hill leur liste. Les pièces fabriquées ou améliorées que possèdent les personnages disparaissent.
USE acore_world;
DELETE FROM npc_vendor WHERE entry IN (3163,3166,3167) AND item BETWEEN 910201 AND 910299;
INSERT IGNORE INTO npc_vendor SELECT * FROM solazeroth_v3_marchands_origine;
DROP TABLE solazeroth_v3_marchands_origine;
DROP TABLE solazeroth_v3_recettes_composants;
DROP TABLE solazeroth_v3_recettes;
DROP TABLE solazeroth_v3_rangs;
DELETE FROM item_template WHERE entry BETWEEN 910201 AND 910299 OR entry BETWEEN 921000 AND 922999;
